import {Game,TOWERS} from './game/simulation.js';
import {VoxelRenderer} from './engine/renderer.js';
import {AudioEngine} from './engine/audio.js';
import {GamepadInput} from './engine/input.js';
const $=id=>document.getElementById(id);
const safeStorage={get(k,d){try{return JSON.parse(localStorage.getItem(k))??d;}catch{return d;}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch{}}};
const game=new Game('gridfall-first-light');
const audio=new AudioEngine();
let selectedCell=game.board.findIndex(n=>!n), selectedNumber=1, paused=false, started=false, notes=true, muted=true, reduced=safeStorage.get('gridfall-motion',matchMedia('(prefers-reduced-motion: reduce)').matches), lastPhase=game.phase, lastUI='', toastTimer, bannerTimer, lastTime=0, runEnded=false;
const renderer=new VoxelRenderer($('gameCanvas'),{onCell:cell=>{if(isBlocked())return;selectedCell=cell;refresh();}});
renderer.setReducedMotion(reduced);document.body.classList.toggle('reduced-motion',reduced);
const towerTypes=['RAPID • SINGLE TARGET','SLOW • CROWD CONTROL','CHAIN • MULTI TARGET','SPLASH • AREA DAMAGE','PIERCE • LINE DAMAGE','POISON • DAMAGE OVER TIME','SUPPORT • ATTACK SPEED','PULL • CROWD CONTROL','BURST • AREA DAMAGE'];
const shortTypes=['Rapid fire','Slow enemies','Chain lightning','Splash damage','Piercing beam','Poison damage','Ally attack buff','Pull enemies','Radial burst'];
const deck=$('towerDeck');
for(const t of TOWERS){const b=document.createElement('button');b.className='tower-card';b.dataset.number=t.number;b.style.setProperty('--tower-color',t.color);b.setAttribute('aria-label',`${t.number}, ${t.name}. ${t.description}`);b.innerHTML=`<span class="tower-num">${t.number}</span><span class="tower-reserve">×1</span><strong>${t.name}</strong><small>${shortTypes[t.number-1]}</small><span class="shortcut">${t.number}</span>`;b.addEventListener('click',()=>{selectNumber(t.number);place();});b.addEventListener('pointerenter',()=>{if(matchMedia('(hover: hover)').matches)inspectTower(t.number);});b.addEventListener('pointerleave',()=>inspectTower(selectedNumber));deck.append(b);}
function notify(message,error=false){if(!message)return;$('statusMessage').textContent=message;$('toast').textContent=message;$('toast').classList.toggle('error',error);$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2400);}
function banner(text){$('floatingBanner').textContent=text;$('floatingBanner').classList.add('show');clearTimeout(bannerTimer);bannerTimer=setTimeout(()=>$('floatingBanner').classList.remove('show'),1500);}
function isBlocked(){return paused||$('helpDialog').open||$('pauseDialog').open;}
function engageAudio(){if(!muted)audio.unlock();}
function selectNumber(number){selectedNumber=((number-1+9)%9)+1;inspectTower(selectedNumber);refresh();}
function inspectTower(n){const t=TOWERS[n-1];$('towerName').textContent=t.name;$('towerDescription').textContent=t.description;$('towerGlyph').textContent=n;$('towerType').textContent=towerTypes[n-1];$('costValue').textContent=`ϟ ${t.cost}`;$('stockValue').textContent=`${game.inventory[n]} IN RESERVE`;document.documentElement.style.setProperty('--selected',t.color);}
function place(){if(isBlocked())return;engageAudio();$('gameCanvas').focus({preventScroll:true});const r=game.place(selectedCell,selectedNumber);if(r.ok){started=true;$('statusMessage').textContent=r.message;const next=findNextBlank(selectedCell);if(game.phase==='solve')selectedCell=next;}else notify(r.message,true);refresh();}
function findNextBlank(cell){for(let i=1;i<=81;i++){const n=(cell+i)%81;if(!game.board[n])return n;}return cell;}
function move(dx,dy){if(isBlocked())return;selectedCell=((Math.floor(selectedCell/9)+dy+9)%9)*9+(selectedCell%9+dx+9)%9;refresh();}
function doHint(){if(isBlocked())return;engageAudio();const r=game.hint();if(r.ok){started=true;selectedCell=r.cell;selectedNumber=r.number;notify('Revealed a correct answer and built its tower.');}else notify(r.message,true);refresh();}
function phaseAction(){if($('pauseDialog').open){if(!runEnded)togglePause();else restart();return;}if($('helpDialog').open){closeHelp();return;}if(paused)return;engageAudio();let r;if(game.phase==='solve'){started=true;r=game.startBattle();}else if(game.phase==='reward'){r=game.nextWave();selectedCell=findNextBlank(selectedCell);}else if(['won','lost'].includes(game.phase)){restart();return;}else{notify('Wave in progress. Place reserve towers to reinforce the grid.');return;}if(!r.ok)notify(r.message,true);refresh();}
function togglePause(){if($('helpDialog').open){closeHelp();return;}if(runEnded)return;paused=!paused;if(paused){$('pauseTitle').textContent='Grid on hold.';$('pauseText').textContent='Your towers can wait.';$('resumeBtn').textContent='Back to the grid →';$('pauseDialog').showModal();audio.stop();}else{$('pauseDialog').close();engageAudio();}refresh();}
function openHelp(){if($('pauseDialog').open)return;$('helpDialog').showModal();audio.stop();}
function closeHelp(){$('helpDialog').close();engageAudio();}
function restart(){engageAudio();game.reset(`gridfall-${Date.now()}`);paused=false;started=false;runEnded=false;lastPhase='solve';selectedCell=game.board.findIndex(n=>!n);selectedNumber=1;$('pauseDialog').close();renderer.particles=[];renderer.labels=[];notify('A fresh grid. A new siege.');refresh();}
function showEnd(){runEnded=true;const won=game.phase==='won';let best=Math.max(game.score,safeStorage.get('gridfall-best',0));safeStorage.set('gridfall-best',best);$('pauseTitle').textContent=won?'Grid secured.':'The core fell.';$('pauseText').textContent=`${won?'Five waves survived. Beautiful work.':'Every siege teaches you something.'} You solved ${game.solvedCount} squares and scored ${game.score.toLocaleString()} points.`;$('resumeBtn').textContent='Play a fresh grid →';$('bestScore').textContent=`BEST SCORE ${best.toLocaleString()}`;$('pauseDialog').showModal();}
function refresh(){const battle=game.phase==='battle',reward=game.phase==='reward',finished=['won','lost'].includes(game.phase);$('app').classList.toggle('battle',battle);$('app').classList.toggle('low-health',game.health<=6);$('navSolve').classList.toggle('active',!battle);$('navBattle').classList.toggle('active',battle);$('waveValue').innerHTML=`${String(game.wave).padStart(2,'0')}<span>/ 05</span>`;$('healthValue').textContent=game.health;$('healthBar').style.width=`${game.health/20*100}%`;$('creditsValue').textContent=game.credits;$('scoreValue').textContent=String(game.score).padStart(4,'0');$('corruptionValue').textContent=`${Math.round(game.corruption*7.5)}%`;$('corruptionValue').style.color=game.corruption?'#ffad7b':'';$('timer').textContent=battle?`${game.enemies.length} LIVE`:reward?'CLEAR':finished?'END':`${String(Math.floor(Math.ceil(game.timer)/60)).padStart(2,'0')}:${String(Math.ceil(game.timer)%60).padStart(2,'0')}`;$('enemyCounter').textContent=battle?`${game.kills} ENEMIES DEFEATED`:reward?'BREACH CONTAINED':'PREPARE YOUR DEFENSE';$('phaseTitle').innerHTML=battle?'The grid is alive.<br>Hold your ground.':reward?'Beautiful chaos.<br>Back to the drawing board.':'A little logic.<br>A lot of firepower.';$('phaseSubtitle').textContent=battle?'Break the rules. Save the core.':reward?`Wave complete. +${game.lastWaveBonus||0} energy.`:'Every answer is a weapon.';$('phaseChip').textContent=battle?'DEFENSE PHASE':reward?'WAVE COMPLETE':'SOLVE PHASE';$('objectiveTitle').textContent=battle?'Make every tower count.':reward?'A moment to regroup.':'Build your advantage.';$('objectiveText').textContent=battle?'Use reserve pieces in blank squares. Illegal moves add enemy strength.':reward?'Buy reserves, then return to solving. Your permanent towers stay.':'Fill the grid. Correct answers become towers and earn energy.';$('boardMode').textContent=battle?'LIVE BATTLEFIELD':reward?'SECTOR SECURED':'TACTICAL GRID';$('routeLabel').textContent=battle?'ENEMY ROUTE LOCKED THIS WAVE':'YOUR MOVES SHAPE THE ROUTE';const total=game.givens.filter(n=>!n).length;$('solveCount').textContent=`${game.solvedCount} / ${total} SOLVED`;$('comboValue').textContent=`${game.combo} STREAK`;$('solveProgress').style.width=`${game.solvedCount/total*100}%`;$('phaseButtonText').textContent=battle?'Defending…':reward?'Next solve phase':finished?'New run':'Launch wave';$('phaseBtn').disabled=battle;$('phaseHint').innerHTML=battle?'Tap a blank + number to deploy':reward?'Towers persist. Keep building. <kbd>Enter</kbd>':!started?'Clock starts with your first answer.':'Beat the clock. <kbd>Enter</kbd> to launch';$('selectedLabel').textContent=`R${Math.floor(selectedCell/9)+1} · C${selectedCell%9+1}`;$('intelTitle').textContent=battle?'EMERGENCY DEPLOYMENT':'FIELD NOTES';const filled=game.board[selectedCell];$('intelText').textContent=filled?(game.givens[selectedCell]?'A printed clue. Build in an empty square.':`Your ${TOWERS[filled-1].name} tower holds this square.`):battle?'Any reserve piece can go here. Wrong answers add +7.5% enemy health.':notes?'Legal candidates for this square:':'Use each digit once per row, column and 3×3 box.';$('candidateList').replaceChildren();if(notes&&!filled&&!battle&&!finished){for(const n of game.candidates(selectedCell)){const b=document.createElement('button');b.textContent=n;b.title=`Place ${n}`;b.onclick=()=>{selectNumber(n);place();};$('candidateList').append(b);}}$('hintBtn').disabled=game.phase!=='solve'||game.credits<6;$('buyBtn').disabled=finished||game.credits<TOWERS[selectedNumber-1].cost;for(const b of deck.children){const n=Number(b.dataset.number);b.classList.toggle('active',n===selectedNumber);b.setAttribute('aria-pressed',String(n===selectedNumber));b.querySelector('.tower-reserve').textContent=`×${game.inventory[n]}`;}inspectTower(selectedNumber);$('motionBtn').textContent=`Reduce motion: ${reduced?'on':'off'}`;$('bestScore').textContent=`BEST SCORE ${safeStorage.get('gridfall-best',0).toLocaleString()}`;}
function buyReserve(){if(isBlocked())return;engageAudio();const r=game.buy(selectedNumber);notify(r.message,!r.ok);$('gameCanvas').focus({preventScroll:true});refresh();}
$('phaseBtn').onclick=phaseAction;$('hintBtn').onclick=doHint;$('buyBtn').onclick=buyReserve;$('helpBtn').onclick=openHelp;$('closeHelp').onclick=closeHelp;$('pauseBtn').onclick=togglePause;$('resumeBtn').onclick=()=>runEnded?restart():togglePause();$('restartBtn').onclick=restart;$('soundBtn').onclick=()=>{muted=!muted;audio.setMuted(muted);if(!muted)audio.unlock();$('soundBtn').classList.toggle('sound-on',!muted);$('soundBtn').title=muted?'Enable sound':'Mute sound';$('soundBtn').setAttribute('aria-label',$('soundBtn').title);notify(muted?'Sound muted.':'Sound on. Headphones recommended.');};$('notesBtn').onclick=()=>{notes=!notes;$('notesBtn').textContent=`◈ Smart notes ${notes?'on':'off'}`;$('notesBtn').setAttribute('aria-pressed',String(notes));refresh();};$('motionBtn').onclick=()=>{reduced=!reduced;safeStorage.set('gridfall-motion',reduced);renderer.setReducedMotion(reduced);document.body.classList.toggle('reduced-motion',reduced);refresh();};
function fullscreen(){if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>{});else document.documentElement.requestFullscreen?.().catch(()=>notify('Fullscreen is unavailable in this browser.'));}$('fullscreenBtn').onclick=fullscreen;
$('pauseDialog').addEventListener('cancel',e=>{e.preventDefault();if(!runEnded)togglePause();});$('helpDialog').addEventListener('cancel',e=>{e.preventDefault();closeHelp();});
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.repeat&& !e.key.startsWith('Arrow'))return;const k=e.key;if(k==='Escape'){if($('helpDialog').open){e.preventDefault();closeHelp();}else if(!$('pauseDialog').open){e.preventDefault();togglePause();}return;}if(k===' '){if(document.activeElement?.tagName==='BUTTON')return;e.preventDefault();if(!$('helpDialog').open)togglePause();return;}if(k.toLowerCase()==='h'){e.preventDefault();if($('helpDialog').open)closeHelp();else openHelp();return;}if(k==='Enter'&&document.activeElement?.tagName!=='BUTTON'){e.preventDefault();phaseAction();return;}if(isBlocked())return;if(k.toLowerCase()==='f'){fullscreen();return;}if(k.toLowerCase()==='b'){e.preventDefault();buyReserve();return;}if(/^[1-9]$/.test(k)){e.preventDefault();selectNumber(Number(k));place();return;}const dirs={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]};if(dirs[k]){e.preventDefault();move(...dirs[k]);}if(k==='Backspace'||k==='Delete'){e.preventDefault();notify('Placed towers are committed for this run.');}});
const controller=new GamepadInput({onMove:move,onNumber:delta=>{if(!isBlocked())selectNumber(selectedNumber+delta);},onAction:action=>{if(action==='phase')phaseAction();else if(action==='place'){if($('helpDialog').open)closeHelp();else if($('pauseDialog').open){if(runEnded)restart();else togglePause();}else place();}else if(action==='hint')doHint();else if(action==='buy')buyReserve();else if(action==='sound')$('soundBtn').click();else if(action==='back'){if($('helpDialog').open)closeHelp();else if($('pauseDialog').open&&!runEnded)togglePause();}},onPause:togglePause,onHelp:()=> $('helpDialog').open?closeHelp():openHelp()});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&started&&!isBlocked()&&!runEnded)togglePause();});
function frame(ms){const dt=Math.min((ms-lastTime)/1000||0,.06);lastTime=ms;controller.update(dt);const blocked=isBlocked();if(!blocked&&started)game.update(dt);if(!blocked&&!muted)audio.update(dt,game.phase);for(const event of game.drainEvents()){renderer.burst(event);if(!blocked&&!muted)audio.play({type:({waveComplete:'reward',combo:'reward',win:'reward',lose:'leak'})[event.type]||event.type,number:event.number});if(event.type==='wave')banner(`WAVE ${game.wave} · INCOMING`);if(event.type==='waveComplete')banner('BREACH CONTAINED');if(event.type==='combo')notify(event.text.replace('coins','energy'));if(event.type==='leak')$('statusMessage').textContent='Core hit! Reinforce the exit with reserve towers.';}
renderer.render({...game,selectedCell,selectedNumber,towerColors:TOWERS.map(t=>t.color)},blocked?0:dt,ms/1000);
const uiKey=[game.phase,Math.ceil(game.timer),game.credits,game.health,game.score,game.enemies.length,game.corruption,game.combo,game.solvedCount,controller.connected].join('|');if(uiKey!==lastUI){refresh();lastUI=uiKey;}if(game.phase!==lastPhase){if(['won','lost'].includes(game.phase))showEnd();lastPhase=game.phase;}$('performanceLabel').textContent=controller.connected?'CONTROLLER CONNECTED':'WEB / DESKTOP';requestAnimationFrame(frame);}
refresh();requestAnimationFrame(frame);
